  // ============ Validation ============
  public static void validateConfig(Bigdata.Config msg) throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate hotWindowHours (assert_ge: 1)
    if (msg.getHotWindowHours() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field hotWindowHours must be >= 1, got: %s", msg.getHotWindowHours()));
    }
    // Validate reheatTtlMinutes (assert_ge: 1)
    if (msg.getReheatTtlMinutes() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field reheatTtlMinutes must be >= 1, got: %s", msg.getReheatTtlMinutes()));
    }
    // Validate warmRetentionDays (assert_ge: 1)
    if (msg.getWarmRetentionDays() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field warmRetentionDays must be >= 1, got: %s", msg.getWarmRetentionDays()));
    }
    // Validate archiveCompactionHours (assert_ge: 1)
    if (msg.getArchiveCompactionHours() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field archiveCompactionHours must be >= 1, got: %s",
              msg.getArchiveCompactionHours()));
    }
    // Validate cacheTtlSeconds (assert_ge: 1)
    if (msg.getCacheTtlSeconds() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field cacheTtlSeconds must be >= 1, got: %s", msg.getCacheTtlSeconds()));
    }
    // Validate timeMaskSeconds (assert_ge: 1)
    if (msg.getTimeMaskSeconds() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field timeMaskSeconds must be >= 1, got: %s", msg.getTimeMaskSeconds()));
    }
    // Validate maxFanOut (assert_ge: 1)
    if (msg.getMaxFanOut() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field maxFanOut must be >= 1, got: %s", msg.getMaxFanOut()));
    }
  }

