  // ============ EnvVar ============
  public static Map<String, String> configToEnvVar(Bigdata.Config msg) {
    Map<String, String> result = new HashMap<>();
    result.put("PROTO_CONFIG_HOT_WINDOW_HOURS", String.valueOf(msg.getHotWindowHours()));
    result.put("PROTO_CONFIG_REHEAT_TTL_MINUTES", String.valueOf(msg.getReheatTtlMinutes()));
    result.put("PROTO_CONFIG_WARM_RETENTION_DAYS", String.valueOf(msg.getWarmRetentionDays()));
    result.put(
        "PROTO_CONFIG_ARCHIVE_COMPACTION_HOURS", String.valueOf(msg.getArchiveCompactionHours()));
    result.put("PROTO_CONFIG_CACHE_TTL_SECONDS", String.valueOf(msg.getCacheTtlSeconds()));
    result.put("PROTO_CONFIG_TIME_MASK_SECONDS", String.valueOf(msg.getTimeMaskSeconds()));
    result.put("PROTO_CONFIG_MAX_FAN_OUT", String.valueOf(msg.getMaxFanOut()));
    return result;
  }

  public static Bigdata.Config.Builder configFromEnvVar(Map<String, String> env) {
    Bigdata.Config.Builder builder = Bigdata.Config.newBuilder();
    String val;
    val = env.get("PROTO_CONFIG_HOT_WINDOW_HOURS");
    if (val != null && !val.isEmpty()) {
      builder.setHotWindowHours(Integer.parseInt(val));
    }
    val = env.get("PROTO_CONFIG_REHEAT_TTL_MINUTES");
    if (val != null && !val.isEmpty()) {
      builder.setReheatTtlMinutes(Integer.parseInt(val));
    }
    val = env.get("PROTO_CONFIG_WARM_RETENTION_DAYS");
    if (val != null && !val.isEmpty()) {
      builder.setWarmRetentionDays(Integer.parseInt(val));
    }
    val = env.get("PROTO_CONFIG_ARCHIVE_COMPACTION_HOURS");
    if (val != null && !val.isEmpty()) {
      builder.setArchiveCompactionHours(Integer.parseInt(val));
    }
    val = env.get("PROTO_CONFIG_CACHE_TTL_SECONDS");
    if (val != null && !val.isEmpty()) {
      builder.setCacheTtlSeconds(Integer.parseInt(val));
    }
    val = env.get("PROTO_CONFIG_TIME_MASK_SECONDS");
    if (val != null && !val.isEmpty()) {
      builder.setTimeMaskSeconds(Integer.parseInt(val));
    }
    val = env.get("PROTO_CONFIG_MAX_FAN_OUT");
    if (val != null && !val.isEmpty()) {
      builder.setMaxFanOut(Integer.parseInt(val));
    }
    return builder;
  }

  public static Map<String, String> bigDataStateToEnvVar(Bigdata.BigDataState msg) {
    Map<String, String> result = new HashMap<>();
    if (msg.hasNodes()) {
      result.putAll(bigDataNodeToEnvVar(msg.getNodes()));
    }
    return result;
  }

  public static Bigdata.BigDataState.Builder bigDataStateFromEnvVar(Map<String, String> env) {
    Bigdata.BigDataState.Builder builder = Bigdata.BigDataState.newBuilder();
    {
      var sub = bigDataNodeFromEnvVar(env).build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setNodes(sub);
      }
    }
    return builder;
  }

  public static Map<String, String> bigDataNodeToEnvVar(Bigdata.BigDataNode msg) {
    Map<String, String> result = new HashMap<>();
    result.put("PROTO_BIG_DATA_NODE_NODE_ID", msg.getNodeId());
    result.put("PROTO_BIG_DATA_NODE_STARTED_AT_MS", String.valueOf(msg.getStartedAtMs()));
    if (msg.hasHzStatus()) {
      result.putAll(storeStatusToEnvVar(msg.getHzStatus()));
    }
    if (msg.hasCassandraStatus()) {
      result.putAll(storeStatusToEnvVar(msg.getCassandraStatus()));
    }
    if (msg.hasIcebergStatus()) {
      result.putAll(storeStatusToEnvVar(msg.getIcebergStatus()));
    }
    return result;
  }

  public static Bigdata.BigDataNode.Builder bigDataNodeFromEnvVar(Map<String, String> env) {
    Bigdata.BigDataNode.Builder builder = Bigdata.BigDataNode.newBuilder();
    String val;
    val = env.get("PROTO_BIG_DATA_NODE_NODE_ID");
    if (val != null && !val.isEmpty()) {
      builder.setNodeId(val);
    }
    val = env.get("PROTO_BIG_DATA_NODE_STARTED_AT_MS");
    if (val != null && !val.isEmpty()) {
      builder.setStartedAtMs(Long.parseLong(val));
    }
    {
      var sub = storeStatusFromEnvVar(env).build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setHzStatus(sub);
      }
    }
    {
      var sub = storeStatusFromEnvVar(env).build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setCassandraStatus(sub);
      }
    }
    {
      var sub = storeStatusFromEnvVar(env).build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setIcebergStatus(sub);
      }
    }
    return builder;
  }

