  public static Bigdata.BigdataConfigState.Builder bigdataConfigStateFromEnvVar(
      Map<String, String> env) {
    Bigdata.BigdataConfigState.Builder builder = Bigdata.BigdataConfigState.newBuilder();
    {
      var sub = configFromEnvVar(env).build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setConfig(sub);
      }
    }
    return builder;
  }

